export const MotionPausedContext = createContext(false);

/** Combines the explicit playback control with the operating-system motion preference. */
export function useQuietMotion() {
  const paused = useContext(MotionPausedContext);
  const reduced = useReducedMotion();
  return paused || !!reduced;
}

/** Adds bounded pointer tilt without touch listeners or a permanent animation loop. */
export function TiltSurface({ children, className = '' }: Readonly<{ children: ReactNode; className?: string }>) {
  const quiet = useQuietMotion();
  return <div className={`tilt-surface ${className}`} onPointerMove={event => {
    if (quiet || event.pointerType !== 'mouse') return;
    const rect = event.currentTarget.getBoundingClientRect();
    event.currentTarget.style.setProperty('--tilt-x', `${((event.clientY - rect.top) / rect.height - .5) * -4}deg`);
    event.currentTarget.style.setProperty('--tilt-y', `${((event.clientX - rect.left) / rect.width - .5) * 5}deg`);
  }} onPointerLeave={event => {
    event.currentTarget.style.setProperty('--tilt-x', '0deg');
    event.currentTarget.style.setProperty('--tilt-y', '0deg');
  }}>{children}</div>;
}

