/** Presents readable ordered steps alongside decorative traveling signals and sequential reveals. */
export function AnimatedFlow({ flow, variant = 'normal' }: Readonly<{ flow: Flow; variant?: 'normal' | 'fallback' }>) {
  const quiet = useQuietMotion();
  return <div className={`flow-block signal-flow ${variant}`} data-ambient="true">
    <h4><GitBranch size={17} />{flow.title}</h4>
    <ol className="architecture-flow">{flow.steps.map((step, index) => <motion.li key={step} style={{ '--step': index } as CSSProperties}
      initial={quiet ? false : { opacity: 0, y: 12 }} whileInView={{ opacity: 1, y: 0 }} viewport={{ once: true }} transition={{ delay: index * .075 }}>
      <span className="flow-number">{String(index + 1).padStart(2, '0')}</span><span>{step}</span>
      {index < flow.steps.length - 1 && <svg className="signal-connector" viewBox="0 0 40 20" aria-hidden="true"><path d="M1 10 H35 M29 4 L35 10 L29 16" /><path className="travel-signal" d="M1 10 H35" /></svg>}
    </motion.li>)}</ol>
  </div>;
}

