/** Illuminates the timeline with actual scroll progress, with a static reduced-motion alternative. */
export function CareerTimeline({ children }: Readonly<{ children: ReactNode }>) {
  const ref = useRef<HTMLDivElement>(null);
  const quiet = useQuietMotion();
  const { scrollYProgress } = useScroll({ target: ref, offset: ['start 75%', 'end 65%'] });
  return <div className="timeline" ref={ref} data-ambient="true"><motion.div className="timeline-progress" aria-hidden="true" style={{ scaleY: quiet ? 1 : scrollYProgress }} />{children}</div>;
}

